{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    # validate
    for i, seg in enumerate(segments):
        required = ['name', 'importance', 'minimum', 'capacity']
        for key in required:
            if key not in seg:
                raise ValueError(f"Missing key '{key}' in segment at index {i}")
        if not isinstance(seg['minimum'], int) or not isinstance(seg['capacity'], int) or not isinstance(seg['importance'], int):
            raise ValueError("Segments must have integer fields")
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum:
        raise ValueError("Budget less than sum of minima")
    if budget > cap_sum:
        raise ValueError("Budget exceeds total capacity")
    allocations = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if allocations[i] >= seg['capacity']:
                continue
            score = seg['importance'] / (allocations[i] + 1)
            if score > best_score or (score == best_score and i < best_idx):
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {}
    for i, seg in enumerate(segments):
        by_name[seg['name']] = allocations[i]
    total = sum(allocations)
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": total
    }"
}
